package com.acrenex.app.activities;
import android.database.Cursor;import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.acrenex.app.database.DatabaseManager;import com.acrenex.app.utils;
public class PredictiveInsightsActivity extends AppCompatActivity{
 @Override protected void onCreate(Bundle b){super.onCreate(b);LinearLayout root=utils.screen(this,"Predictive Governance Insights","Decision-support indicators for workload prioritization — not automated legal decisions.");DatabaseManager m=new DatabaseManager(this);Cursor c=m.getDatabase().rawQuery("SELECT current_status,COUNT(*),AVG(progress) FROM applications GROUP BY current_status",null);try{while(c.moveToNext()){double p=c.getDouble(2);String outlook=p>=75?"Near completion":p>=50?"Mid-workflow":"Early workflow";LinearLayout box=utils.column(this);box.addView(utils.text(this,c.getString(0),17,utils.TEXT,true));utils.row(box,this,"Applications",String.valueOf(c.getInt(1)));utils.row(box,this,"Average progress",String.format(java.util.Locale.US,"%.0f%%",p));box.addView(utils.badge(this,outlook,p>=50));utils.addCard(root,box,this);}}finally{c.close();}root.addView(utils.text(this,"Model note: this prototype uses transparent rule-based indicators. A production system can replace the rules with validated ML models trained on authorized, de-identified departmental data.",12,utils.MUTED,false));utils.setScreenContentView(this, root);}
}
